// spec rng правило 12: setState / getState — состояние от окружения целиком.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRng } from '../core/rng.mjs';

test('getState/setState: копия состояния продолжает ту же последовательность', () => {
  const a = makeRng(5);
  for (let i = 0; i < 7; i++) a.u32();
  const snap = a.getState();
  assert.equal(snap.state.length, 16);
  assert.equal(snap.index, a.getState().index);
  const b = makeRng(99);
  b.setState(snap);
  for (let i = 0; i < 40; i++) assert.equal(b.u32(), a.u32());
});

test('setState копирует снимок и не меняет сохранённый сид', () => {
  const r = makeRng(7);
  const snap = { state: Array.from({ length: 16 }, (_, i) => i * 2654435761 >>> 0), index: 3 };
  r.setState(snap);
  assert.equal(r.getSeed(), 7);
  const before = JSON.stringify(snap);
  r.u32();
  r.u32();
  assert.equal(JSON.stringify(snap), before);
  const g = r.getState();
  g.state[0] ^= 1;
  assert.notEqual(r.getState().state[0], g.state[0]);
});

test('getState сразу после засева = состояние правила 3, индекс 0; setSeed сбрасывает состояние', () => {
  const r = makeRng(1);
  assert.equal(r.getState().index, 0);
  r.u32();
  r.setSeed(1);
  assert.deepEqual(r.getState(), makeRng(1).getState());
});

test('setState: плохой снимок — ошибка', () => {
  const r = makeRng(0);
  assert.throws(() => r.setState({ state: [1, 2], index: 0 }));
  assert.throws(() => r.setState({ state: Array(16).fill(0), index: 16 }));
});
